import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";

/* Helper function to get unique identifier for events*/
export const getEventId = (item: EventTimelineItem) => {
  const eventType =
    item?.eventOrTransactionId?.tag === "EventId"
      ? item?.eventOrTransactionId?.inner?.eventId
      : null;

  return eventType;
};

/** Returns eventId if confirmed, or transactionId for local echoes. */
export const getItemUniqueKey = (item: EventTimelineItem): string | null => {
  const id = item?.eventOrTransactionId;
  if (!id) return null;
  if (id.tag === "EventId") return id.inner.eventId ?? null;
  if (id.tag === "TransactionId") return id.inner.transactionId ?? null;
  return null;
};

/** Returns the transactionId for a local echo, or null if already confirmed. */
export const getTransactionId = (item: EventTimelineItem): string | null => {
  const id = item?.eventOrTransactionId;
  if (id?.tag === "TransactionId") return id.inner.transactionId ?? null;
  return null;
};

