case TimelineDiff_Tags.Set: {
  const { index, value } = diff.inner;
  const ev = toEventItem(value);
  const oldItem = timelineItems[index];
  const oldTxId = oldItem ? getTransactionId(oldItem) : null;

  timelineItems[index] = ev;

  // Detect txId→eventId transition: old item was a local echo, new item is confirmed.
  // Use the specific txId from the replaced item (not FIFO shift) so out-of-order
  // confirmations don't mismatch queue entries.
  if (oldTxId && ev && !getTransactionId(ev)) {
    const queueIdx = pendingTransactionIdsQueue.current.indexOf(oldTxId);
    if (queueIdx !== -1) {
      pendingTransactionIdsQueue.current.splice(queueIdx, 1);
    }
    // Remove any stale duplicate local echo still present elsewhere in the list.
    const dupeIdx = timelineItems.findIndex((item, i) => {
      if (i === index || !item) return false;
      return getItemUniqueKey(item) === oldTxId;
    });
    if (dupeIdx !== -1) {
      timelineItems.splice(dupeIdx, 1);
    }
  }
  break;
}

